class Fancy:
    def __init__(self):
        self.vals = []
        self.MOD = 10**9 + 7
        self.cur_add = 0
        self.cur_mul = 1

    def append(self, val: int) -> None:
        inv_mul = pow(self.cur_mul, self.MOD - 2, self.MOD)
        adjusted = (val - self.cur_add) * inv_mul % self.MOD
        self.vals.append(adjusted)

    def addAll(self, inc: int) -> None:
        self.cur_add = (self.cur_add + inc) % self.MOD

    def multAll(self, m: int) -> None:
        self.cur_mul = self.cur_mul * m % self.MOD
        self.cur_add = self.cur_add * m % self.MOD

    def getIndex(self, idx: int) -> int:
        if idx >= len(self.vals):
            return -1
        return (self.vals[idx] * self.cur_mul + self.cur_add) % self.MOD

