class Solution:
    def addPoly(self, poly1, poly2):
        dummy = Node(0, 0)
        cur = dummy
        p1, p2 = poly1, poly2
        while p1 and p2:
            if p1.power > p2.power:
                cur.next = p1
                p1 = p1.next
            elif p1.power < p2.power:
                cur.next = p2
                p2 = p2.next
            else:
                coeff = p1.coefficient + p2.coefficient
                if coeff != 0:
                    cur.next = Node(coeff, p1.power)
                    cur = cur.next
                p1, p2 = p1.next, p2.next
                continue
            cur = cur.next
        cur.next = p1 or p2
        return dummy.next

