class Solution:
    def numWays(self, words, target: str) -> int:
        MOD = 10**9 + 7
        m, k = len(target), len(words[0])
        cnt = [[0]*26 for _ in range(k)]
        for w in words:
            for j, c in enumerate(w):
                cnt[j][ord(c)-ord('a')] += 1
        dp = [0] * (m + 1)
        dp[0] = 1
        for j in range(k):
            for i in range(min(m, j+1), 0, -1):
                dp[i] = (dp[i] + dp[i-1] * cnt[j][ord(target[i-1])-ord('a')]) % MOD
        return dp[m]

