class Solution:
    def lowestCommonAncestor(self, root, p, q):
        self.found_p = self.found_q = False
        res = self.dfs(root, p, q)
        return res if self.found_p and self.found_q else None
    def dfs(self, node, p, q):
        if not node:
            return None
        left = self.dfs(node.left, p, q)
        right = self.dfs(node.right, p, q)
        if node == p:
            self.found_p = True
            return node
        if node == q:
            self.found_q = True
            return node
        if left and right:
            return node
        return left or right

