class Solution:
    def createSortedArray(self, instructions) -> int:
        MOD = 10**9 + 7
        m = max(instructions)
        tree = [0] * (m + 1)
        def update(i):
            while i <= m:
                tree[i] += 1
                i += i & (-i)
        def query(i):
            s = 0
            while i > 0:
                s += tree[i]
                i -= i & (-i)
            return s
        res = 0
        for i, val in enumerate(instructions):
            left = query(val - 1)
            right = i - query(val)
            res = (res + min(left, right)) % MOD
            update(val)
        return res

