class Solution:
    def correctBinaryTree(self, root):
        queue = deque([(root, None, False)])
        visited = set()
        while queue:
            for _ in range(len(queue)):
                node, parent, is_left = queue.popleft()
                if node.right and node.right.val in visited:
                    if is_left:
                        parent.left = None
                    else:
                        parent.right = None
                    return root
                visited.add(node.val)
                if node.right:
                    queue.append((node.right, node, False))
                if node.left:
                    queue.append((node.left, node, True))
        return root

