class Solution:
    def waysToMakeFair(self, nums) -> int:
        n = len(nums)
        right_even = sum(nums[i] for i in range(0, n, 2))
        right_odd = sum(nums[i] for i in range(1, n, 2))
        left_even = left_odd = 0
        res = 0
        for i in range(n):
            if i % 2 == 0:
                right_even -= nums[i]
            else:
                right_odd -= nums[i]
            # after removal: left_even + right_odd == left_odd + right_even?
            if left_even + right_odd == left_odd + right_even:
                res += 1
            if i % 2 == 0:
                left_even += nums[i]
            else:
                left_odd += nums[i]
        return res

