class Solution:
    def flipBinaryTree(self, root, leaf):
        def dfs(node, prev):
            parent = node.parent
            node.parent = prev
            if node.left == prev:
                node.left = None
            if node.right == prev:
                node.right = None
            if parent:
                child = dfs(parent, node)
                if node.left:
                    node.right = child
                else:
                    node.left = child
            return node
        # disconnect leaf
        p = leaf.parent
        if p.left == leaf:
            p.left = None
        else:
            p.right = None
        leaf.parent = None
        child = dfs(p, leaf)
        if leaf.left:
            leaf.right = child
        else:
            leaf.left = child
        return leaf

