class FrontMiddleBackQueue:
    def __init__(self):
        self.front = deque()
        self.back = deque()

    def _balance(self):
        while len(self.front) > len(self.back):
            self.back.appendleft(self.front.pop())
        while len(self.front) < len(self.back) - 1:
            self.front.append(self.back.popleft())

    def pushFront(self, val: int) -> None:
        self.front.appendleft(val)
        self._balance()

    def pushMiddle(self, val: int) -> None:
        if len(self.front) < len(self.back):
            self.front.append(val)
        else:
            self.back.appendleft(val)

    def pushBack(self, val: int) -> None:
        self.back.append(val)
        self._balance()

    def popFront(self) -> int:
        if not self.front and not self.back:
            return -1
        if self.front:
            val = self.front.popleft()
        else:
            val = self.back.popleft()
        self._balance()
        return val

    def popMiddle(self) -> int:
        if not self.back:
            return -1
        if len(self.front) == len(self.back):
            val = self.front.pop()
        else:
            val = self.back.popleft()
        self._balance()
        return val

    def popBack(self) -> int:
        if not self.back:
            return -1
        val = self.back.pop()
        self._balance()
        return val

import bisect
class Solution:
    def minimumMountainRemovals(self, nums) -> int:
        n = len(nums)
        # LIS ending at i
        lis = [0] * n
        tails = []
        for i in range(n):
            pos = bisect.bisect_left(tails, nums[i])
            if pos == len(tails):
                tails.append(nums[i])
            else:
                tails[pos] = nums[i]
            lis[i] = pos + 1
        # LDS starting at i (LIS from right)
        lds = [0] * n
        tails = []
        for i in range(n-1, -1, -1):
            pos = bisect.bisect_left(tails, nums[i])
            if pos == len(tails):
                tails.append(nums[i])
            else:
                tails[pos] = nums[i]
            lds[i] = pos + 1
        max_mountain = 0
        for i in range(1, n-1):
            if lis[i] > 1 and lds[i] > 1:
                max_mountain = max(max_mountain, lis[i] + lds[i] - 1)
        return n - max_mountain

