class Solution:
    def maxOperations(self, nums, k: int) -> int:
        cnt = Counter(nums)
        res = 0
        for num in list(cnt.keys()):
            comp = k - num
            if comp == num:
                res += cnt[num] // 2
            elif comp in cnt:
                pairs = min(cnt[num], cnt[comp])
                res += pairs
                cnt[num] -= pairs
                cnt[comp] -= pairs
        return res

